import { one, type Chapter } from "../../schema";

function ch(
  id: string,
  number: number,
  title: string,
  heading: string,
  paragraphs: Chapter["paragraphs"],
): Chapter {
  return { id, number, title, heading, paragraphs };
}

export const prideChapters: Chapter[] = [
  ch("cap-10", 10, "Caput X", "De primo superbiae gradu, qui est curiositas", [
    one(
      "p28",
      "28",
      "Primus itaque superbiae gradus est curiositas. Hanc autem talibus indiciis deprehendes: si videris monachum, de quo prius bene confidebas, ubicumque stat, ambulat, sedet, oculis incipientem vagari, caput erectum, aures portare suspensas, e motibus exterioris hominis interiorem immutatum agnoscas. Vir quippe perversus nictat oculo, terit pede, digito loquitur, et ex insolenti corporis motu, recens animae morbus deprehenditur, quam, dum a sui circumspectione torpescit incuria sui, curiosam in alios facit. Quia enim seipsam ignorat, foras mittitur, ut haedos pascat. Haedos quippe, qui peccatum significant, recte oculos auresque appellaverim, quoniam sicut mors per peccatum in orbem, sic per has fenestras intrat ad mentem. In his ergo pascendis se occupat curiosus, dum scire non curat qualem se reliquerit intus. Et vere si te vigilanter, homo, attendas, mirum est si ad aliud umquam intendas. Audi, curiose, Salomonem; audi, stulte, Sapientem: Omni custodia, inquit, custodi cor tuum. Quo enim a te, o curiose, recedis? Cui te interim committis? Vt quid audes oculos levare ad caelum, qui peccasti in caelum? Terram intuere, ut cognoscas teipsum. Ipsa te tibi repraesentabit, quia terra es et in terram ibis.",
      "The first degree of pride is curiosity. This you may detect by the following signs. Look at that monk, whom you have hitherto supposed to be a sensible man. He has now taken to staring about him, whether he is standing up, walking about or sitting down. He thrusts his head forward, and pricks up his ears. From his outward movements you can clearly see the inward change. For it is the froward man who winketh with the eye, presseth with the foot, and speaketh with the finger, and from the unusual movements of his body is seen to have lately contracted disease of the soul — the careless sluggishness of which in self-examination makes it inquisitive about others. So since it takes no heed to itself it is sent out of doors to feed the kids. And as these are the types of sin, I may quite correctly give the title of ‘kids’ to the eyes and the ears, since as death comes into the world through sin, so does sin enter the mind through these apertures. The curious man, therefore, busies himself with feeding them, though he takes no trouble to ascertain the state in which he has left himself. You inquisitive fellow, listen to Solomon: With all watchfulness guard thy heart. For whither, inquisitive man, will you retire from your own presence? How dare you, who have sinned against heaven, lift up your eyes to the sky? Look down to the earth if you want to recognize yourself. It will show you what you are, for earth thou art, and to earth shalt thou go.",
      "The first degree of pride, then, is curiosity. And you will catch this by such signs: if you shall have seen a monk, of whom you previously well trusted, wherever he stands, walks, sits, beginning to wander with the eyes, the head erect, carrying the ears suspended, from the motions of the exterior man you may recognize the interior changed. For a perverse man winks with the eye, rubs with the foot, speaks with the finger, and from the insolent motion of the body a recent disease of the soul is caught, which, while it grows numb from circumspection of itself by carelessness of itself, makes it curious toward others. Because it does not know itself, it is sent outside, to feed the kids. Kids indeed, who signify sin, I would rightly have called eyes and ears, since as death through sin into the world, so through these windows it enters to the mind. In feeding these, then, the curious man occupies himself, while he does not care to know of what sort he has left himself within. And truly if you attend to yourself vigilantly, man, it is a wonder if you ever intend toward another thing. Hear, curious one, Solomon; hear, fool, the Wise: With all custody, he says, guard your heart. For whither do you withdraw from yourself, O curious one? To whom do you meanwhile commit yourself? Why do you dare to lift eyes to heaven, you who have sinned against heaven? Look upon the earth, that you may know yourself. It will present you to yourself, because you are earth and you will go into the earth.",
      [
        {
          kind: "word",
          title: "curiositas / inquisitive",
          body: "Bernard’s first step is curiositas. Mills often says ‘inquisitive’. The close line keeps curious so the later Lucifer material and the retractatio’s Seraphim remain one vice.",
        },
      ],
    ),
    one(
      "p29",
      "29",
      "Duabus tamen causis inculpabiliter oculos levas, ut vel petas auxilium, vel impendas. Levavit oculos suos David in montes, ut peteret; levavit et Dominus super turbas, ut impenderet: alter miserabiliter, alter misericorditer, ambo inculpabiliter. Tu quoque si locum, tempus et causam considerans, tua vel fratris necessitate oculos levas, non solum non culpo, sed et plurimum laudo. Hoc enim excusat miseria, illud commendat misericordia. Sin alias, non Prophetae, non Domini, sed Dinae aut Evae, immo ipsius Satanae imitatorem te dixerim. Dina namque, dum ad pascendos haedos egreditur, ipsa patri, et sua sibi virginitas rapitur. O Dina, quid necesse est ut videas mulieres alienigenas? Qua necessitate? Qua utilitate? An sola curiositate?",
      "Now there are two reasons for which you may raise your eyes without being to blame — one is to seek, the other is to render, assistance. David raised his eyes to the mountains for the former, the Lord lifted His over the crowd for the latter purpose. The motive of the one was misfortune, that of the other was mercy, neither was to blame. If you likewise with due regard to place, time and occasion, look up when you or a brother are in distress, I not only do not blame you, I highly commend you. For misfortune allows the one action, mercy approves the other. But in different circumstances I should call you an imitator not of the Prophet nor of the Lord, but of Dina or of Eve, aye, verily, of Satan himself. For Dina when she went out to feed her kids, was snatched away from her father and her maidenhood was taken from her. O Dina, what need was there for thee to look on strange women? Was it necessary — did it serve any useful purpose — or was it done out of mere curiosity?",
      "Yet for two causes you lift the eyes without blame, that you may either ask help, or bestow it. David lifted his eyes to the mountains, that he might ask; the Lord also lifted them over the crowds, that he might bestow: the one miserably, the other mercifully, both without blame. You also, if considering place, time and cause, you lift the eyes by your necessity or a brother’s, I not only do not blame, but I also praise greatly. For misery excuses this, mercy commends that. But if otherwise, I would have called you an imitator not of the Prophet, not of the Lord, but of Dinah or of Eve, nay of Satan himself. For Dinah, while she goes out to feed the kids, herself is snatched from her father, and her virginity from herself. O Dinah, what need is there that you see foreign women? By what necessity? By what usefulness? Or by curiosity alone?",
    ),
    one(
      "p30",
      "30",
      "Tu quoque, o Eva, in paradiso posita es, ut cum viro tuo opereris et custodias illum. Omne lignum paradisi ad vescendum tibi conceditur, praeter illud quod dicitur scientiae boni et mali. Quid tuam mortem tam intente intueris? Quid illo tam crebro vagantia lumina iacis? Quid spectare libet, quod manducare non licet? Oculos, inquis, tendo, non manum. Non est interdictum ne videam, sed ne comedam. Ad quod Apostolus: Omnia mihi licent, sed non omnia expediunt. Etsi culpa non est, culpae tamen indicium est. Nisi enim mens minus se curiose servaret, tua curiositas tempus vacuum non haberet. Te enim intenta ad aliud, latenter interim in cor tuum serpens illabitur. Offert tandem prohibitum, et aufert concessum: porrigit pomum, et surripit paradisum.",
      "And thou, O Eve, wast placed in Paradise, that thou mightest work with thine husband and bestow thy care on him. Leave was given to thee to eat of every tree in Paradise, except that one which is called the tree of knowledge of good and evil. Why lookest thou so eagerly for thy death? Why dost thou so often cast in that direction those wandering eyes of thine? What pleasure hast thou in looking on that which thou mayest not eat? Perchance thou dost reply, ‘I stretch forth mine eyes not my hand. It is not looking but eating that is forbidden.’ To which the Apostle shall answer, All things are lawful for me, but all things are not expedient. Although it may not be in itself a guilty act, it affords an incentive to sin. For if thy mind had not shown insufficient attention to its own condition, it would have had no time for idle curiosity. For while thou art thinking of something else, the serpent creeps craftily into thine heart. At length he offers what is forbidden and takes away what is allowed. He presents thee with fruit and deprives thee of Paradise.",
      "You also, O Eve, are placed in paradise, that you may work with your man and guard it. Every tree of paradise is granted you for eating, except that which is called of the knowledge of good and evil. Why do you look so intently on your death? Why do you so often cast wandering lights upon that? Why is it pleasing to look at what it is not permitted to eat? The eyes, you say, I stretch, not the hand. It is not forbidden that I may not see, but that I may not eat. To which the Apostle: All things are permitted me, but not all things are expedient. Even if it is not a fault, it is nevertheless a sign of a fault. For unless the mind were guarding itself less curiously, your curiosity would not have empty time. For you, intent on another thing, the serpent meanwhile secretly slips into your heart. At last he offers the forbidden, and takes away the granted: he holds out an apple, and steals paradise.",
    ),
    one("p31", "31", "Sed et tu, signaculum similitudinis, non in paradiso, sed in deliciis paradisi Dei positus es. Quid amplius quaerere debes? Plenus sapientia et perfectus decore, altiora te ne quaesieris et fortiora te ne scrutatus fueris. Sta in te, ne cadas a te, si ambulas in magnis et in mirabilibus super te. Sed quid interim ex obliquo intendis ad aquilonem? Iam te video, iam te perspicio nescio quae supra te curiosius alta rimantem. Ponam, inquis, sedem meam ad Aquilonem. Ceteris astantibus caelicolis, dum tu sedere solus affectas, fratrum concordiam, totius caelestis patriae pacem, ipsius, quantum in te est, quietem Trinitatis infestas.", "And as for thee, ‘pattern of perfection,’ thou wast placed not in Paradise, but in Eden the garden of God. What more couldst thou reasonably desire? Filled with wisdom, and exalted in honour, thou shouldst have expected nothing higher. Remain where thou art, lest thou fall from thy position, if thou walkest among things that are too great and wonderful for thee. But why dost thou sometimes turn round and look to the north? I see thee peering too inquisitively into the unknown heights above thee. I will place, sayest thou, my throne towards the north. The other dwellers in heaven are standing, whilst thou alone dost desire to sit, and dost thereby disturb the harmony of the brethren, the peace of the whole heavenly community, and, so far as it lies in thy power, the tranquillity of the Trinity.", "But you also, seal of likeness, are placed not in paradise, but in the delights of the paradise of God. What more ought you to seek? Full of wisdom and perfect in beauty, do not seek things higher than you and do not have scrutinized things stronger than you. Stand in yourself, lest you fall from yourself, if you walk in great and wonderful things above you. But why meanwhile do you intend from the side toward the north? Already I see you, already I look through you searching too curiously I know not what high things above you. I will place, you say, my seat toward the North. The other heaven-dwellers standing by, while you alone desire to sit, you assail the concord of the brothers, the peace of the whole heavenly homeland, the rest of the Trinity itself, as much as is in you."),
    one("p32", "32", "Quo te tua, miser, curiositas ducit, ut praesumptione singulari non dubites civibus scandalum, iniuriam facere Regi? Millia millium ministrant ei, et decies centena millia assistunt ei, ubi nemo sedere perhibetur, nisi solus is qui sedet super Cherubim, cui a ceteris ministratur; et tu nescio quae prae ceteris differentius prospiciendo, curiosius inquirendo, irreverentius pervadendo, sedem tibi collocas in caelo, ut sis similis Altissimo?", "Does this curiosity carry thee so far, thou wretched being, that with unrivalled presumption thou dost not scruple to give offence to the citizens and to do injury to the king? Thousands of thousands minister to him and ten times a hundred thousand stand before him, where no one is allowed to sit, but He alone who sitteth upon the cherubims. And dost thou — claiming a wider outlook, a more incisive scrutiny and a freer entrance than that of the others — place a seat for thyself in heaven, that thou mayest be on a level with the Most High?", "Whither does your curiosity, miserable one, lead you, that by a singular presumption you do not hesitate to make scandal for the citizens, injury for the King? Thousands of thousands minister to him, and ten times a hundred thousand stand by him, where no one is reported to sit, except he alone who sits upon the Cherubim, to whom it is ministered by the rest; and you, looking out I know not what more differently before the rest, inquiring more curiously, invading more irreverently, place a seat for yourself in heaven, that you may be like the Most High?"),
    one("p33", "33", "Hoc est enim, o impie, hoc est quod cogitas; haec est iniquitas quam meditaris in cubili tuo, et dicis: Putas Creator opus suum destruat? Scio quidem quia non latet Deum qualiscumque cogitatio mea: Deus enim est. Nec placet ei talis cogitatio mea, quia bonus est. Sed nec si velit, ego effugiam manus eius, quia potens est. Te ergo fallis, non Deum. Et quia de magno eius bono in te, tu magnum in eum excogitas malum, merito iniquitas tua invenitur ad odium.", "For this, and nothing less than this, thou unholy one, is thy train of thought. This is the wickedness that thou dost devise on thy bed, and sayest, ‘Thinkest thou that the Creator will destroy His own work? I am well aware that no thought of mine escapes God, because He is God, nor does any such thought please Him, because He is good. Nor can I escape His hand — if He so wishes — because He is mighty.’ Thou deceivest thyself, not God. And because from His great good toward thee thou devisest a great evil against Him, deservedly is thy iniquity found unto hatred.", "For this is, O impious one, this is what you think; this is the iniquity which you meditate on your bed, and you say: Do you think the Creator will destroy his work? I know indeed that whatever thought of mine is not hidden from God: for he is God. Nor does such a thought of mine please him, because he is good. But neither, if he should wish, shall I flee his hands, because he is powerful. You therefore deceive yourself, not God. And because from his great good in you, you think out a great evil against him, deservedly is your iniquity found unto hatred."),
    one("p34", "34", "Caelum, inquit, mihi sedes est, terra autem scabellum pedum meorum. Non dixit Oriens aut Occidens aut una aliqua caeli plaga, sed totum caelum mihi sedes est. Non potes ergo in parte sedere caeli, cum ille totum elegerit sibi. In terra non potes, quia pedum eius scabellum est. Quid facies? E caelo pulsus, in terris remanere non potes. Elige ergo tibi in aere locum, non ad sedendum, sed ad volandum, ut qui tentasti concutere statum aeternitatis, poenam sentias propriae fluctuationis.", "Hear now this calumny: Heaven, he says, is my seat, but the earth the footstool of my feet. He did not say East or West or some one region of heaven, but the whole heaven is my seat. You cannot therefore sit in a part of heaven, since he has chosen the whole for himself. On earth you cannot, because it is the footstool of his feet. What will you do? Driven from heaven, you cannot remain on the lands. Choose therefore for yourself a place in the air, not for sitting, but for flying, that you who tried to shake the standing of eternity may feel the punishment of your own fluctuation.", "Heaven, he says, is a seat for me, but the earth the footstool of my feet. He did not say East or West or some one region of heaven, but the whole heaven is a seat for me. You cannot therefore sit in a part of heaven, since he has chosen the whole for himself. On earth you cannot, because it is the footstool of his feet. What will you do? Driven from heaven, you cannot remain on the lands. Choose therefore for yourself a place in the air, not for sitting but for flying, that you who tried to shake the standing of eternity may feel the punishment of your own fluctuation."),
    one("p35", "35", "Seraphim namque aliis quidem alis suae contemplationis de throno ad scabellum, de scabello ad thronum volantia, aliis caput Domini pedesque velantia, ad hoc ibi posita puto, ut sicut peccanti homini paradisi per Cherubim prohibetur ingressus, ita et per Seraphim suae curiositati modus imponatur.", "For the Seraphim, flying with certain wings of their contemplation from the throne to the footstool and from the footstool to the throne, covering with others the Lord’s head and feet, I suppose were placed there for this, that as entry to paradise is forbidden to the sinning man through the Cherubim, so also through the Seraphim a limit may be set to his curiosity.", "For the Seraphim, flying with certain wings of their contemplation from the throne to the footstool, from the footstool to the throne, covering with others the Lord’s head and feet, I suppose were placed there for this, that as for the sinning man the entry of paradise is forbidden through the Cherubim, so also through the Seraphim a measure may be imposed on his curiosity.", [{ kind: "text", title: "puto and the retractatio", body: "Bernard later confessed he had never heard or read this opinion about the Seraphim, and that puto was meant as a conjecture. The close line keeps I suppose." }]),
    one("p36", "36", "O Lucifer, qui mane oriebaris, immo non iam lucifer, sed noctifer, aut etiam mortifer, rectus cursus tuus erat ab Oriente ad Meridiem, et tu praepostero ordine tendis ad Aquilonem? Quanto magis ad alta festinas, tanto celerius ad occasum declinas.", "O Lucifer, who wast rising in the morning — nay, no longer light-bearer, but night-bearer, or even death-bearer — thy right course was from the East to the South, and thou in inverted order stretchest toward the North? The more thou hastenest to the heights, the more swiftly thou declinest toward setting.", "O Lucifer, who were rising in the morning — nay, no longer light-bearer, but night-bearer, or even death-bearer — your right course was from the East to the South, and you in inverted order stretch toward the North? By how much more you hasten to high things, by so much more swiftly you decline toward setting."),
    one("p37", "37", "Velim tamen curiosius, o curiose, intentionem tuae curiositatis inquirere. Ponam, inquis, sedem meam ad Aquilonem. Nec Aquilonem hunc corporalem, nec sedem hanc, cum sis spiritus, intelligo materialem. Puto autem per Aquilonem reprobandos homines fuisse designatos, per sedem potestatem in illos.", "I would nevertheless inquire more curiously, O curious one, into the intention of your curiosity. I will place, you say, my seat toward the North. I understand neither this North as bodily, nor this seat as material, since you are a spirit. But I suppose that through the North men to be rejected were designated, through the seat power over them.", "I would nevertheless inquire more curiously, O curious one, into the intention of your curiosity. I will place, you say, my seat toward the North. I understand neither this North as bodily, nor this seat as material, since you are a spirit. But I suppose that through the North men to be rejected were designated, through the seat power over them."),
    one(
      "p38",
      "38",
      "Iure igitur in gradibus superbiae primum curiositas vindicat sibi, quae etiam inventa est initium omnis esse peccati. Reprobus Angelus per curiositatem a veritate cecidit, quia prius spectavit curiose, quod affectavit illicite, speravit praesumptuose. Sed nisi haec citius cohibeatur, in levitatem animi, quae secundus gradus est, cito delabitur.",
      "Rightly therefore in the degrees of pride does curiosity claim the first for itself, which has also been found to be the beginning of every sin. The reprobate Angel fell from the truth through curiosity, because he first looked curiously at what he desired illicitly, hoped presumptuously. But unless this is more quickly restrained, it quickly slides down into lightness of mind, which is the second degree.",
      "Rightly therefore in the degrees of pride does curiosity claim the first for itself, which has also been found to be the beginning of every sin. The reprobate Angel fell from the truth through curiosity, because he first looked curiously at what he desired illicitly, hoped presumptuously. But unless this is more quickly restrained, it quickly slides down into lightness of mind, which is the second degree.",
    ),
  ]),
  ch("cap-11", 11, "Caput XI", "De secundo gradu superbiae, qui est levitas animi", [
    one("p39", "39", "Monachus enim, qui sui negligens, alios curiose circumspicit, dum quosdam suspicit superiores, quosdam despicit inferiores, et in aliis quidem videt quod invidet, in aliis quod irridet. Inde fit ut pro mobilitate oculorum levigatus animus, nulla utique sui cura aggravatus, modo per superbiam ad alta se erigat, modo per invidiam in ima demergat: nunc per invidiam nequiter tabescit, nunc pro excellentia pueriliter hilarescit. In altero nequam, in altero vanus, in utroque superbus exsistit, quia et quod superari se dolet, et quod superare se gaudet, amor propriae excellentiae facit. Has autem animi vicissitudines nunc pauca et mordacia, nunc multa et inania, nunc risu, nunc luctu plena, semper vero irrationabilia indicant verba. Compara, si vis, hos duos primos superbiae gradus supremis duobus humilitatis, et vide si non in ultimo curiositas, in penultimo levitas cohibetur: idipsum in ceteris reperies, si alterutrum comparentur.", "The monk who, neglecting himself, looks curiously around at others, while he looks up to certain as superiors, looks down on certain as inferiors, and in some indeed sees what he envies, in others what he mocks. Thence it happens that the mind, made light by the mobility of the eyes, weighed down by no care of itself, now through pride raises itself to high things, now through envy sinks into the depths: now through envy it wastes wickedly, now for excellence it grows boyishly cheerful. In the one worthless, in the other vain, in both he exists proud, because both that he grieves to be surpassed, and that he rejoices to surpass, the love of his own excellence makes. And these vicissitudes of mind — now few and biting, now many and empty, now full of laughter, now of mourning, but always irrational — words indicate. Compare, if you wish, these first two degrees of pride with the highest two of humility, and see whether curiosity is not restrained in the last, lightness in the last-but-one: you will find the same in the rest, if they are compared each to each.", "For the monk who, neglecting himself, looks curiously around at others, while he looks up to certain as superiors, looks down on certain as inferiors, and in some indeed sees what he envies, in others what he mocks. Thence it happens that the mind, made light by the mobility of the eyes, weighed down by no care of itself at all, now through pride raises itself to high things, now through envy sinks into the lowest: now through envy it wastes wickedly, now for excellence it grows boyishly cheerful. In the one worthless, in the other vain, in both he exists proud, because both that he grieves to be surpassed, and that he rejoices to surpass, the love of his own excellence makes. And these vicissitudes of mind now few and biting, now many and empty, now full of laughter, now of mourning, but always irrational, words indicate. Compare, if you wish, these first two degrees of pride with the highest two of humility, and see if curiosity is not restrained in the last, lightness in the last-but-one: you will find the very same in the rest, if they are compared each with each."),
  ]),
  ch("cap-12", 12, "Caput XII", "De tertio gradu superbiae, qui est inepta laetitia", [
    one("p40", "40", "Proprium est superborum, laeta semper appetere et tristia devitare, iuxta illud: Cor stultorum, ubi laetitia. Vnde et monachus, qui duos iam superbiae gradus descendit, dum per curiositatem ad animi levitatem devenit, cum gaudium, quod semper appetit, frequenti videt interpolari tristitia, quam de bonis alterius contrahit, impatiens suae humiliationis, fugit ad consilium falsae consolationis. Ex illa denique parte, qua sua sibi vilitas et aliena excellentia monstratur, restringit curiositatem, ut totum se transferat in contrariam partem, quatenus in quo ipse videtur praecellere, curiosius notet, in quo alter praecellit, semper dissimulet, ut dum devitat quod triste putatur, laetitia continuetur. Sicque fit, ut quem sibi vicissim vindicabant gaudium et tristitia, sola possidere incipiat inepta laetitia. Illum qui eiusmodi est, aut raro, aut numquam gementem audies, lacrimantem videbis. In signis scurrilitas, in fronte hilaritas, vanitas apparet in incessu. Pronus ad iocum, facilis ac promptus in risu. Cunctis quippe quae in se contemptibilia, et ideo tristia noverat, a memoria rasis, bonisque, si qua sentit in se, adunatis vel simulatis ante oculos mentis, dum nil cogitat nisi quod libet, nec attendit si licet, iam risum tenere, iam ineptam laetitiam dissimulare non valet. Vt enim vesica collecto turgida vento punctoque forata exiguo, si stringitur, crepitat dum detumescit, sic monachus, ubi vanis scurrilibusque cor suum cogitationibus impleverit, propter disciplinam silentii non inveniens ventus vanitatis qua plenius egrediatur, inter angustias faucium per cachinnos excutitur.", "It is proper to the proud always to seek joyful things and to avoid sad ones, according to that: The heart of fools, where there is gladness. Whence also the monk who has already descended two degrees of pride, while through curiosity he comes to lightness of mind, when he sees the joy which he always seeks frequently interrupted by the sadness which he contracts from another’s goods, impatient of his humiliation, flees to the counsel of false consolation. From that side, finally, on which his own cheapness and another’s excellence is shown to him, he restrains curiosity, that he may transfer himself wholly to the contrary side, so that he may more curiously note that in which he himself seems to excel, and always conceal that in which the other excels, so that while he avoids what is thought sad, gladness may be continued. And so it happens that him whom joy and sadness were claiming in turn, unfitting gladness alone begins to possess. Him who is of this kind you will hear groaning rarely or never, you will see weeping. In signs scurrility, on the brow cheerfulness, vanity appears in the gait. Prone to a joke, easy and prompt in laughter. For all things which he had known contemptible in himself, and therefore sad, having been scraped from memory, and the goods, if he feels any in himself, gathered or simulated before the eyes of the mind, while he thinks nothing except what pleases, nor attends whether it is permitted, he is already unable to hold laughter, already unable to hide unfitting gladness. For as a bladder swollen with gathered wind and pierced by a small point, if it is squeezed, crackles while it goes down, so the monk, when he has filled his heart with vain and scurrilous thoughts, the wind of vanity not finding, because of the discipline of silence, where it may go out more fully, is shaken out through guffaws between the narrows of the throat.", "It is proper to the proud always to seek joyful things and to avoid sad ones, according to that: The heart of fools, where gladness is. Whence also the monk who has already descended two degrees of pride, while through curiosity he comes down to lightness of mind, when he sees the joy which he always seeks frequently interrupted by the sadness which he contracts from another’s goods, impatient of his humiliation, flees to the counsel of a false consolation. From that part, finally, by which his cheapness to himself and another’s excellence is shown, he restrains curiosity, that he may transfer himself wholly into the contrary part, so that he may more curiously note that in which he himself seems to excel, always conceal that in which the other excels, so that while he avoids what is thought sad, gladness may be continued. And so it is made, that him whom joy and sadness were claiming in turn, unfitting gladness alone begins to possess. Him who is of this sort you will hear groaning either rarely or never, you will see weeping. In signs scurrility, on the brow cheerfulness, vanity appears in the walk. Prone to a joke, easy and ready in laughter. For all things which he had known contemptible in himself, and therefore sad, scraped from memory, and goods, if he feels any in himself, united or simulated before the eyes of the mind, while he thinks nothing except what pleases, nor attends whether it is allowed, he is already unable to hold laughter, already unable to dissimulate unfitting gladness. For as a bladder swollen with gathered wind and pierced by a small point, if it is squeezed, crackles while it deflates, so the monk, when he shall have filled his heart with vain and scurrilous thoughts, the wind of vanity not finding, because of the discipline of silence, where it may go out more fully, is shaken out through guffaws among the narrows of the jaws."),
  ]),
  ch("cap-13", 13, "Caput XIII", "De quarto gradu, qui est iactantia", [
    one("p41", "41", "At postquam vanitas crescere et vesica grossescere coeperit, necesse est ut ampliori foramine, laxato sinu, ventositas eructuetur; aliquin rumpetur. Sic monachus, inepta redundante laetitia, dum risu vel signis eam aperire non sufficit, in Heliu verba prorumpit: En venter meus quasi mustum absque spiraculo, quod lagunculas novas dirumpit. Aut loquetur ergo, aut rumpetur. Plenus est enim sermonibus, et coarctat eum spiritus uteri sui. Esurit et sitit auditores, quibus suas iactitet vanitates, quibus omne quod sentit effundat, quibus qualis et quantus sit innotescat. Inventa autem occasione loquendi, si de litteris sermo exoritur, vetera proferuntur et nova; volant sententiae, verba resonant ampullosa. Praevenit interrogantem, non quaerenti respondet. Ipse quaerit, ipse soluit, et verba collocutoris imperfecta praecidit. Non curat te docere vel a te discere ipse quod nescit, sed ut scire sciatur quod scit. Si de religione agitur, statim visiones et somnia proferuntur. Deinde laudat ieiunia, commendat vigilias, super omnia orationes exaltat; de patientia, de humilitate, aut de singulis virtutibus plenissime, sed vanissime disputat. Si ad ludicra sermo convertitur, in his quanto assuetior, tanto loquacior invenitur. Et ut totum in brevi colligam: in multiloquio nota iactantiam. In hoc habes quartum gradum et descriptum et nominatum. Fuge rem, et tene nomen.", "But after vanity has begun to grow and the bladder to thicken, it is necessary that, the opening having been widened, the windiness be belched; otherwise it will burst. So the monk, unfitting gladness overflowing, while he does not suffice to open it by laughter or signs, breaks forth into the words of Elihu: Behold my belly is as must without a vent, which bursts new bottles. He will therefore either speak, or be burst. For he is full of speeches, and the spirit of his belly constrains him. He hungers and thirsts for hearers, to whom he may boast his vanities, to whom he may pour out all he feels, to whom of what sort and how great he is may become known. And an occasion of speaking having been found, if talk arises about letters, old things and new are brought forth; sentences fly, swollen words resound. He anticipates the one asking, he answers the one not seeking. He himself asks, he himself solves, and he cuts off the interlocutor’s unfinished words. He does not care to teach you or to learn from you what he does not know, but that what he knows may be known to be known. If it is a matter of religion, at once visions and dreams are brought forth. Then he praises fasts, commends vigils, exalts prayers above all; about patience, about humility, or about single virtues he disputes most fully, but most vainly. If talk is turned to sports, in these the more accustomed, the more talkative he is found. And that I may gather the whole in brief: in much speaking mark boasting. In this you have the fourth degree both described and named. Flee the thing, and hold the name.", "But after vanity has begun to grow and the bladder to thicken, it is necessary that by a wider hole, the fold having been loosened, the windiness be belched; otherwise it will be burst. So the monk, unfitting gladness overflowing, while he does not suffice to open it by laughter or signs, breaks forth into Elihu’s words: Behold my belly is as must without a breathing-hole, which bursts new flasks. He will therefore either speak, or be burst. For he is full of speeches, and the spirit of his belly constrains him. He hungers and thirsts for hearers, to whom he may boast his vanities, to whom he may pour out everything he feels, to whom of what sort and how great he is may become known. And an occasion of speaking having been found, if speech arises about letters, old things are brought forth and new; sentences fly, swollen words resound. He comes before the one asking, he answers the one not seeking. He himself asks, he himself looses, and he cuts off the interlocutor’s unfinished words. He does not care to teach you or himself to learn from you what he does not know, but that what he knows may be known to be known. If it is treated of religion, at once visions and dreams are brought forth. Then he praises fasts, commends vigils, exalts prayers above all; about patience, about humility, or about the single virtues he disputes most fully, but most vainly. If speech is turned to play, in these by how much more accustomed, by so much more talkative he is found. And that I may gather the whole in brief: in much-speaking mark boasting. In this you have the fourth degree both described and named. Flee the thing, and hold the name."),
  ]),
  ch("cap-14", 14, "Caput XIV", "De quinto gradu superbiae, qui dicitur singularitas", [
    one("p42", "42", "Turpe est ei, quo se supra ceteros iactat, si non plus ceteris aliquid agat, per quod ultra ceteros appareat. Proinde non sufficit ei quod communis monasterii regula vel maiorum cohortantur exempla. Nec tamen melior esse studet, sed videri. Non melius vivere, sed videri vincere gestit, quatenus dicere possit: Non sum sicut ceteri hominum. Plus sibi blanditur de uno ieiunio, quod ceteris prandentibus facit, quam si cum ceteris septem dies ieiunaverit. Commodior sibi videtur una oratiuncula peculiaris, quam tota psalmodia unius noctis. Inter prandendum crebro solet oculos iactare per mensas, ut si quem minus comedere viderit, victum se doleat. Ad omnia denique sua strenuus, ad communia piger. Vigilat in lecto, dormit in choro; cumque aliis psallentibus ad vigilias tota nocte dormitet, post vigilias, aliis in claustro quiescentibus, solus in oratorio remanet.", "It is shameful to him, by which he boasts himself above the rest, if he does not do something more than the rest, through which he may appear beyond the rest. Hence what the common rule of the monastery or the examples of the elders exhort is not enough for him. Nor nevertheless does he study to be better, but to be seen. He does not desire to live better, but to be seen to conquer, so that he may be able to say: I am not like the rest of men. He flatters himself more about one fast, which he makes while the rest are dining, than if he shall have fasted seven days with the rest. One peculiar little prayer seems more convenient to him than the whole psalmody of one night. During dining he is accustomed frequently to cast eyes through the tables, that if he shall have seen someone eat less, he may grieve himself conquered. Finally strenuous toward all his own things, sluggish toward common ones. He watches in bed, sleeps in choir; and when, the others psalming at vigils, he dozes the whole night, after vigils, the others resting in the cloister, he remains alone in the oratory.", "It is shameful to him, by which he casts himself above the rest, if he does not do something more than the rest, through which he may appear beyond the rest. Hence it is not enough for him that the common rule of the monastery or the examples of the greater ones exhort. Nor nevertheless does he study to be better, but to be seen. He does not long to live better, but to be seen to win, so that he may be able to say: I am not like the rest of men. He flatters himself more from one fast, which he makes while the rest are dining, than if with the rest he shall have fasted seven days. One peculiar little prayer seems more convenient to him than the whole psalmody of one night. During dining he is accustomed frequently to cast eyes through the tables, that if he shall have seen someone eat less, he may grieve himself beaten. Finally strenuous toward all his own, sluggish toward common things. He watches in bed, sleeps in choir; and when with others psalming at vigils he dozes the whole night, after vigils, others resting in the cloister, he remains alone in the oratory."),
  ]),
  ch("cap-15", 15, "Caput XV", "De sexto gradu superbiae, id est arrogantia", [
    one("p43", "43", "Credit quod audit, laudat quod agit, et quid intendat non attendit. Obliviscitur intentionem, dum amplectitur opinionem. Quique de omni alia re plus sibi credit quam aliis, de se solo plus aliis credit quam sibi, ut iam non verbotenus aut sola operum ostentatione suam praeferat religionem, sed intimo cordis credat affectu se omnibus sanctiorem; et quidquid de se laudatum agnoverit, non ignorantiae aut benevolentiae laudatoris, sed suis meritis arroganter ascribit. Vnde post singularitatem, sextum sibi gradum iure arrogantia vindicavit.", "He believes what he hears, praises what he does, and does not attend to what he intends. He forgets intention, while he embraces opinion. And he who about every other thing believes himself more than others, about himself alone believes others more than himself, so that now he may prefer his religion not in word only or by mere ostentation of works, but by the inmost affection of the heart may believe himself holier than all; and whatever he shall have recognized praised about himself, he arrogantly ascribes not to the ignorance or benevolence of the praiser, but to his own merits. Whence after singularity, arrogance has rightly claimed the sixth degree for itself.", "He believes what he hears, praises what he does, and does not attend to what he intends. He forgets the intention, while he embraces the opinion. And he who about every other thing believes himself more than others, about himself alone believes others more than himself, so that now he may not prefer his religion in word only or by mere display of works, but by the inmost affection of the heart may believe himself holier than all; and whatever praised about himself he shall have recognized, he arrogantly ascribes not to the ignorance or benevolence of the praiser, but to his merits. Whence after singularity, arrogance has rightly claimed the sixth degree for itself."),
  ]),
  ch("cap-16", 16, "Caput XVI", "De septimo gradu superbiae, qui est praesumptio", [
    one("p44", "44", "Qui enim alios se praecellere putat, quomodo plus de se quam de aliis non praesumat? Primus in conventibus residet, in consiliis primus respondet; non vocatus accedit, non iussus se intromittit; reordinat ordinata, reficit facta. Quidquid ipse non fecerit aut ordinaverit, nec recte factum, nec pulchre aestimat ordinatum. Iudicat iudicantes, praeiudicat iudicaturis. Si, cum tempus advenerit, non promoveatur ad prioratum, suum abbatem aut invidum iudicat, aut deceptum. Quod si mediocris ei aliqua oboedientia iniuncta fuerit, indignatur, aspernatur, arbitrans se non esse minoribus occupandum, qui se ad maiora sentit idoneum. Si ergo, cum argutus fuerit, declinare cor eius videris in verba malitiae, in octavum gradum, qui dicitur defensio peccatorum, noveris corruisse.", "For he who thinks that he excels others, how should he not presume more about himself than about others? He sits first in gatherings, answers first in counsels; not called he approaches, not ordered he inserts himself; he reorders things ordered, remakes things made. Whatever he himself shall not have done or ordered, he judges neither rightly done, nor beautifully ordered. He judges those judging, prejudges those about to judge. If, when the time shall have come, he is not promoted to the priorate, he judges his abbot either envious, or deceived. But if some middling obedience shall have been enjoined on him, he is indignant, he scorns, judging that he is not to be occupied with lesser things, who feels himself fit for greater. If therefore, when he shall have been argued, you shall have seen his heart decline into words of malice, you will know that he has fallen into the eighth degree, which is called defence of sins.", "For he who thinks that he excels others, how does he not presume more about himself than about others? First he sits in gatherings, in counsels he answers first; not called he approaches, not ordered he puts himself in; he reorders things ordered, remakes things made. Whatever he himself shall not have done or ordered, he estimates neither rightly done, nor beautifully ordered. He judges those judging, prejudges those about to be judged. If, when the time shall have arrived, he is not promoted to the priorate, he judges his abbot either envious, or deceived. But if some middling obedience shall have been enjoined on him, he is indignant, he scorns, judging that he is not to be occupied with lesser things, who feels himself fit for greater. If therefore, when he shall have been argued, you shall have seen his heart decline into words of malice, you will have known that he has rushed down into the eighth degree, which is called defence of sins."),
  ]),
  ch("cap-17", 17, "Caput XVII", "De octavo gradu, qui est defensio peccatorum", [
    one("p45", "45", "Multis vero modis fiunt excusationes in peccatis. Aut enim dicit qui se excusat: Non feci, aut: Feci quidem, sed bene feci, aut si male, Non multum male; aut si multum male, Non mala intentione. Si autem et de illa, sicut Adam vel Eva, convincitur, aliena suasione excusare se nititur. Sed qui procaciter etiam aperta defendit, quando occultas et malas cogitationes, cordi suo advenientes, humiliter revelaret abbati?", "But excuses in sins are made in many ways. For either he who excuses himself says: I did not do it, or: I did it indeed, but I did well, or if badly, Not very badly; or if very badly, Not with a bad intention. But if he is convicted also about that, like Adam or Eve, he strives to excuse himself by another’s persuasion. But he who shamelessly defends even open things — when would he humbly reveal hidden and bad thoughts, arriving at his heart, to the abbot?", "But excuses in sins are made in many ways. For either he who excuses himself says: I did not do, or: I did indeed, but I did well, or if badly, Not much badly; or if much badly, Not with a bad intention. But if he is convicted also about that, like Adam or Eve, he strives to excuse himself by another’s persuasion. But he who shamelessly defends even open things, when would he humbly reveal hidden and evil thoughts, arriving at his heart, to the abbot?"),
  ]),
  ch("cap-18", 18, "Caput XVIII", "De nono gradu superbiae, qui est simulata confessio", [
    one("p46", "46", "Licet vero genera haec excusationis eatenus mala iudicentur, quatenus ore prophetico verba malitiae appellentur, multo tamen periculosior est fallax ac superba confessio, quam pervicax et obstinata defensio. Nonnulli enim, cum de apertioribus arguuntur, scientes, si se defenderent, quod sibi non crederetur, subtilius inveniunt argumentum defensionis, verba respondentes dolosae confessionis. Est quippe, ut scriptum est, qui nequiter humiliat se, et interiora eius plena sunt dolo. Vultus demittitur, prosternitur corpus; aliquas sibi lacrimulas extorquent, si possunt. Nec solum qui eiusmodi est obiecta non excusat, sed ipse quoque culpam exaggerat, ut dum impossibile aliquid aut incredibile culpae suae ore ipsius additum audis, etiam illud, quod ratum putabas, discredere possis. Malunt enim apud homines veritate periclitari quam humilitate, cum apud Deum periclitentur utrimque.", "Although these kinds of excuse are judged evil insofar as they are called by the prophetic mouth words of malice, yet a deceitful and proud confession is much more dangerous than a stubborn and obstinate defence. For some, when they are argued about more open things, knowing that if they defended themselves they would not be believed, find a subtler argument of defence, answering the words of a deceitful confession. For there is, as it is written, one who wickedly humbles himself, and his interiors are full of deceit. The face is cast down, the body is prostrated; they wring some little tears for themselves, if they can. Nor does he who is of this kind only not excuse the things objected, but he himself also exaggerates the fault, so that while you hear something impossible or incredible added to his fault from his own mouth, you can disbelieve even that which you thought established. For they prefer to be endangered among men in truth than in humility, although before God they are endangered on both sides.", "Although these kinds of excuse are judged evil insofar as they are called by the prophetic mouth words of malice, yet a deceitful and proud confession is much more dangerous than a stubborn and obstinate defence. For some, when they are argued about more open things, knowing that if they defended themselves it would not be believed to them, find more subtly an argument of defence, answering the words of a deceitful confession. For there is, as it is written, one who wickedly humbles himself, and his interiors are full of deceit. The countenance is sent down, the body is prostrated; they extort some little tears for themselves, if they can. Nor does he who is of this kind only not excuse things objected, but he himself also exaggerates the fault, so that while you hear something impossible or incredible added to his fault from his own mouth, you can disbelieve even that which you thought ratified. For they prefer to be endangered among men by truth than by humility, although before God they are endangered on both sides."),
    one("p47", "47", "Gloriosa res humilitas, qua ipsa quoque superbia palliare se appetit, ne vilescat! Sed haec cito tergiversatio a praelato deprehenditur. Vasa figuli probat fornax, et tribulatio vere paenitentes discernit. Qui enim veraciter paenitet, laborem paenitentiae non abhorret. Cuius vero simulata confessio est, una vel levi contumelia aut exigua poena interrogatus, iam humilitatem simulare, iam simulationem dissimulare non potest. Murmurat, frendet, irascitur, nec in quarto stare humilitatis, sed in nonum superbiae gradum corruisse probatur.", "A glorious thing is humility, with which pride itself also desires to cloak itself, lest it become cheap! But this tergiversation is quickly caught by the prelate. The furnace proves the potter’s vessels, and tribulation discerns those truly penitent. For he who truly repents does not shrink from the labour of penitence. But he whose confession is simulated, questioned by one even light insult or a slight penalty, can already not simulate humility, already not hide the simulation. He murmurs, he gnashes, he is angry, and is proved not to have stood in the fourth of humility, but to have fallen into the ninth degree of pride.", "A glorious thing is humility, by which pride itself also desires to cloak itself, lest it become cheap! But this turning-about is quickly caught by the prelate. The furnace proves the potter’s vessels, and tribulation discerns those truly penitent. For he who truly repents does not shrink from the labour of penitence. But of whom the confession is simulated, questioned by one even light insult or a slight punishment, he already cannot simulate humility, already cannot hide the simulation. He murmurs, he gnashes, he is angered, and is proved not to stand in the fourth of humility, but to have rushed down into the ninth degree of pride."),
  ]),
  ch("cap-19", 19, "Caput XIX", "De decimo gradu superbiae, qui est rebellio", [
    one("p48", "48", "Hic, nisi eum miseratio superna respiciat, ut — quod valde talibus difficile est — universorum iudiciis tacitus acquiescat, frontosus mox et impudens factus, tanto deterius quanto desperatius in decimum gradum per rebellionem corruit, quique prius latenter arrogans fratres contempserat, iam patenter inoboediens etiam magistrum contemnit.", "Here, unless heavenly pity look upon him, so that — what is very difficult for such — he silently acquiesce in the judgments of all, soon made brazen and shameless, by so much worse as more desperately he rushes down into the tenth degree through rebellion, and he who previously, secretly arrogant, had despised the brothers, now openly disobedient despises even the master.", "Here, unless heavenly pity look back upon him, so that — what is very difficult for such — he silently acquiesce in the judgments of all, soon made brazen and shameless, by so much worse as more desperately he rushes through rebellion into the tenth degree, and he who previously, secretly arrogant, had despised the brothers, now openly disobedient despises even the master."),
    one("p49", "49", "Sciendum namque, quod omnes gradus, quos in duodecim partitus sum, in tres tantummodo colligi possunt, ut in sex superioribus contemptus fratrum, in quatuor sequentibus contemptus magistri, in duobus, qui restant, consummetur contemptus Dei. Notandum quoque, quod hi duo ultimi superbiae gradus, qui et humilitatis ascendendo primi inveniuntur, sicut extra congregationem ascendendi sunt, ita in congregatione descendi non possunt. Quod autem ante ascendi debeant, ex hoc aperte intelligi datur, quod de tertio gradu in Regula legitur: Tertius, inquit, gradus est, ut quis pro Dei amore omni oboedientia se subdat maiori. Si ergo in tertio gradu subiectio collocatur, quae procul dubio fit, quando primum novitius conventui sociatur, consequens est quod duo iam anteriores transcensi intelligantur.", "For it is to be known that all the degrees which I have partitioned into twelve can be gathered into three only, so that in the six higher the contempt of the brothers, in the four following the contempt of the master, in the two that remain the contempt of God is consummated. It is also to be noted that these two last degrees of pride, which are also found first in ascending humility, as they are to be ascended outside the congregation, so they cannot be descended in the congregation. But that they ought to be ascended before is openly given to be understood from this, that about the third degree it is read in the Rule: The third, it says, degree is, that one for the love of God subject himself by all obedience to a greater. If therefore subjection is placed in the third degree, which beyond doubt is done when first a novice is associated to the convent, it follows that the two earlier are already understood as having been crossed.", "For it is to be known that all the degrees which I have divided into twelve can be gathered into three only, so that in the six higher the contempt of the brothers, in the four following the contempt of the master, in the two that remain the contempt of God is consummated. It is to be noted also that these two last degrees of pride, which also in ascending are found first of humility, as they are to be ascended outside the congregation, so they cannot be descended in the congregation. But that they ought to be ascended before is given to be understood openly from this, that about the third degree it is read in the Rule: The third, it says, degree is, that one for the love of God subject himself by every obedience to a greater. If therefore in the third degree subjection is placed, which beyond doubt is done when first a novice is associated to the convent, it is consequent that the two already earlier are understood as crossed."),
  ]),
  ch("cap-20", 20, "Caput XX", "De undecimo gradu superbiae, qui est libertas peccandi", [
    one("p50", "50", "Post decimum itaque gradum, qui rebellio dictus est, expulsus vel egressus de monasterio statim excipitur ab undecimo. Et tunc ingreditur vias, quae videntur hominibus bonae, quarum finis — nisi forte Deus eas sibi saepierit — demerget eum in profundum inferni, id est in contemptum Dei. Impius, siquidem, cum venerit in profundum malorum, contemnit. Potest autem undecimus gradus appellari libertas peccandi, per quam monachus, cum iam nec magistrum videt quem timeat, nec fratres quos revereatur, tanto securius quanto liberius sua desideria implere delectatur, a quibus in monasterio tam pudore quam timore prohibebatur. Sed etsi iam vel fratres vel abbatem non timet, nondum tamen Dei penitus formidine caret. Hanc ratio, tenuiter adhuc submurmurans, voluntati proponit, nec sine aliqua dubitatione quaeque primum illicita perficit.", "After the tenth degree, then, which has been called rebellion, expelled or having gone out from the monastery he is at once received by the eleventh. And then he enters ways that seem good to men, whose end — unless perhaps God shall have fenced them for himself — will sink him into the depth of hell, that is into contempt of God. The impious, indeed, when he shall have come into the depth of evils, despises. And the eleventh degree can be called liberty of sinning, through which the monk, when he now sees neither a master whom he may fear, nor brothers whom he may revere, is delighted to fulfill his desires by so much more securely as more freely, from which in the monastery he was prohibited as much by shame as by fear. But even if he now fears neither the brothers nor the abbot, he does not yet wholly lack the fear of God. Reason, still thinly murmuring underneath, proposes this to the will, nor without some doubt does he first accomplish whatever illicit things.", "After the tenth degree, then, which has been called rebellion, expelled or having gone out from the monastery he is at once taken up by the eleventh. And then he enters ways that seem good to men, whose end — unless perhaps God shall have hedged them for himself — will sink him into the deep of hell, that is into the contempt of God. The impious, indeed, when he shall have come into the deep of evils, despises. And the eleventh degree can be called liberty of sinning, through which the monk, when now he sees neither a master whom he may fear, nor brothers whom he may revere, is delighted to fulfill his desires by so much more securely as more freely, from which in the monastery he was prohibited as much by shame as by fear. But even if he now does not fear either the brothers or the abbot, he does not yet wholly lack the dread of God. Reason, still thinly murmuring underneath, proposes this to the will, nor without some hesitation does he first accomplish whatever illicit things."),
  ]),
  ch("cap-21", 21, "Caput XXI", "De duodecimo gradu superbiae, qui est consuetudo peccandi", [
    one("p51", "51", "Et postquam terribili Dei iudicio prima flagitia impunitas sequitur, experta voluptas libenter repetitur, repetita blanditur. Concupiscentia reviviscens, sopitur ratio, ligat consuetudo. Trahitur miser in profundum malorum, traditur captivus tyrannidi vitiorum, ita ut carnalium voragine desideriorum absorptus, suae rationis divinique timoris oblitus, dicat insipiens in corde suo: Non est Deus. Iam indifferenter libitis pro licitis utitur. Quemadmodum denique ascensis his omnibus gradibus, corde iam alacri et absque labore pro bona consuetudine iustus currit ad vitam, sic descensis impius eisdem, pro malo usu non se ratione gubernans, intrepidus festinat ad mortem. Supremus tantum et infimus currunt absque impedimento et absque labore. Ad mortem hic, ad vitam ille festinat. Illum alacrem charitas, hunc proclivem cupiditas facit. In illo denique perfecta charitas, in isto consummata iniquitas foras mittit timorem. Potest ergo duodecimus gradus appellari consuetudo peccandi, qua Dei metus amittitur, contemptus incurritur.", "And after, by the terrible judgment of God, impunity follows the first crimes, the pleasure experienced is gladly repeated, the repeated flatters. Concupiscence reviving, reason is put to sleep, custom binds. The miserable one is drawn into the depth of evils, is handed over captive to the tyranny of vices, so that, absorbed by the whirlpool of carnal desires, forgetful of his reason and of divine fear, the fool says in his heart: There is no God. Already he uses pleasing things indifferently for permitted ones. Finally, as, all these degrees having been ascended, the just man, with a heart already eager and without labour because of good custom, runs to life, so the impious, the same having been descended, not governing himself by reason because of bad use, hastens undaunted to death. Only the highest and the lowest run without impediment and without labour. To death this one, to life that one hastens. Charity makes that one eager, cupidity this one downhill. Finally in that one perfect charity, in this one consummated iniquity, casts fear outside. The twelfth degree, then, can be called the custom of sinning, by which the fear of God is lost, contempt is incurred.", "And after, by the terrible judgment of God, impunity follows the first outrages, the pleasure experienced is gladly repeated, the repeated flatters. Desire reviving, reason is lulled, custom binds. The miserable one is dragged into the deep of evils, is handed over captive to the tyranny of vices, so that, swallowed by the whirlpool of carnal desires, forgetful of his reason and of divine fear, the unwise says in his heart: There is no God. Already he uses liked things indifferently for allowed ones. Finally, as, all these degrees having been ascended, with a heart already eager and without labour because of good custom the just man runs to life, so the impious, the same having been descended, not governing himself by reason because of bad use, hastens fearless to death. Only the highest and the lowest run without impediment and without labour. To death this one, to life that one hastens. Charity makes that one eager, cupidity this one sloping-down. Finally in that one perfect charity, in this one consummated iniquity, sends fear outside. The twelfth degree, then, can be called the custom of sinning, by which the fear of God is lost, contempt is incurred."),
  ]),
  ch("cap-22", 22, "Caput XXII", "Prayer for the brother already dead in soul", [
    one("p52", "52", "Pro tali iam, inquit Ioannes apostolus, non dico ut quis oret. Sed numquid dicis, o Apostole, ut quis desperet? Immo gemat qui illum amat. Non praesumat orare, nec desistat plorare. Audi credentem, sperantem, nec tamen orantem: Domine, inquit, si fuisses hic, frater meus non fuisset mortuus. Magna fides, qua credit sua praesentia Dominum mortem prohibere potuisse. Sed et nunc, inquit, scio, quia quaecumque poposceris a Deo, dabit tibi Deus. Petri quoque post gravem lapsum lacrimam quidem video, sed precem non audio; nec tamen de indulgentia dubito.", "For such a one already, says the apostle John, I do not say that anyone should pray. But do you say, O Apostle, that anyone should despair? Nay, let him groan who loves him. Let him not presume to pray, nor cease to weep. Hear one believing, hoping, and yet not praying: Lord, she says, if you had been here, my brother would not have been dead. Great faith, by which she believes that by his presence the Lord could have prohibited death. But even now, she says, I know that whatever you shall have asked from God, God will give you. Of Peter also after a heavy fall I see a tear indeed, but I do not hear a prayer; nor nevertheless do I doubt about indulgence.", "For such a one already, says John the apostle, I do not say that anyone should pray. But do you say, O Apostle, that anyone should despair? Nay, let him groan who loves him. Let him not presume to pray, nor let him cease to weep. Hear one believing, hoping, and yet not praying: Lord, she says, if you had been here, my brother would not have been dead. Great faith, by which she believes that by his presence the Lord could have forbidden death. But even now, she says, I know that whatever things you shall have asked from God, God will give you. Of Peter also after a heavy fall I see a tear indeed, but I do not hear a prayer; nor nevertheless do I doubt about indulgence."),
    one("p53", "53", "Quid est quod dico? An forte ullum remanet spei refugium, ubi oratio non invenit locum? Audi credentem, sperantem, nec tamen orantem: Domine, si fuisses hic, frater meus non fuisset mortuus. Magna fides, qua credit sua praesentia Dominum mortem prohibere potuisse, si adfuisset. Modo autem quid? Absit ut quem credidit vivum potuisse servare, mortuum dubitet posse resuscitare. Sed et nunc, inquit, scio, quia quaecumque poposceris a Deo, dabit tibi Deus.", "What is it that I say? Does perhaps any refuge of hope remain, where prayer does not find a place? Hear one believing, hoping, and yet not praying: Lord, if you had been here, my brother would not have been dead. Great faith, by which she believes that by his presence the Lord could have prohibited death, if he had been present. But now what? Far be it that she whom she believed able to keep alive should doubt able to raise the dead. But even now, she says, I know that whatever you shall have asked from God, God will give you.", "What is it that I say? Does perhaps any refuge of hope remain, where prayer does not find a place? Hear one believing, hoping, and yet not praying: Lord, if you had been here, my brother would not have been dead. Great faith, by which she believes that by his presence the Lord could have forbidden death, if he had been present. But now what? Far be it that she should doubt that he whom she believed able to keep alive is able to raise the dead. But even now, she says, I know that whatever you shall have asked from God, God will give you."),
    one("p54", "54", "Deinde quaerenti ubi posuissent eum, respondet: Veni et vide. O Martha, magna nobis fidei tuae insignia tribuis; sed quomodo cum tanta fide diffidis? Veni, inquis, et vide. Cur, si non desperas, non sequeris, et dicis: Et resuscita? Si autem desperas, cur magistrum sine causa fatigas? An forte fides aliquando recipit, quod oratio non praesumit: ut gemat potius quam petat, ploret potius quam precetur?", "Then to him asking where they had placed him, she answers: Come and see. O Martha, you give us great signs of your faith; but how with so great faith do you distrust? Come, you say, and see. Why, if you do not despair, do you not follow, and say: And raise him? But if you despair, why do you weary the master without cause? Or does perhaps faith sometimes receive what prayer does not presume: that she groan rather than ask, weep rather than pray?", "Then to him asking where they had placed him, she answers: Come and see. O Martha, you grant us great insignia of your faith; but how with so great faith do you distrust? Come, you say, and see. Why, if you do not despair, do you not follow, and say: And raise? But if you despair, why do you weary the master without cause? Or does faith perhaps sometimes receive what prayer does not presume: that she groan rather than ask, weep rather than pray?"),
    one("p55", "55", "Simili etiam forma si contigerit, quod Deus avertat, aliquem de nostris fratribus, non in corpore, sed in anima mori, quamdiu adhuc inter nos erit, pulsabo et ego meis qualiscumque peccator, pulsabo et fratrum precibus Salvatorem. Si revixerit, lucrati erimus fratrem. Mortuum autem dixerim illum, qui sua peccata defendens, in octavum iam corruit gradum. A mortuo enim, tamquam qui non est, perit confessio. Post decimum vero, quo tertius est ab octavo, iam effertur in libertatem peccandi, quando expellitur a consortio monasterii. At postquam quartum transierit, iam recte quatriduanus dicitur, dum in quintum decidens per consuetudinem sepelitur.", "In a similar form also if it shall have happened — which God avert — that someone of our brothers die, not in body but in soul, as long as he will still be among us, I also, a sinner of whatever sort, will knock, I will knock also with the brothers’ prayers upon the Saviour. If he shall have lived again, we shall have gained a brother. But I would have called him dead, who, defending his sins, has already fallen into the eighth degree. For from a dead man, as from one who is not, confession perishes. But after the tenth, which is third from the eighth, he is already carried out into the liberty of sinning, when he is expelled from the companionship of the monastery. But after he shall have crossed the fourth, he is already rightly called four-days-dead, while falling into the fifth he is buried through custom.", "In a similar form also if it shall have happened, which God avert, that someone of our brothers die, not in the body but in the soul, as long as he will still be among us, I also will knock with mine, a sinner of whatever sort, I will knock also with the brothers’ prayers upon the Saviour. If he shall have lived again, we shall have gained a brother. But I would have said him dead, who, defending his sins, has already rushed down into the eighth degree. For from a dead man, as from one who is not, confession perishes. But after the tenth, which is third from the eighth, he is already carried out into liberty of sinning, when he is expelled from the companionship of the monastery. But after he shall have crossed the fourth, he is already rightly called of four days, while falling into the fifth he is buried through custom."),
    one("p56", "56", "Absit autem a nobis, ut etiam pro talibus, etsi palam non praesumimus, vel in cordibus nostris orare cessemus, cum Paulus eos quoque lugeret, quos sine paenitentia mortuos sciret. Viderint tamen in quanto periculo sint, pro quibus Ecclesia palam orare non audeat, quae fidenter etiam pro Iudaeis, pro haereticis, pro gentilibus orat.", "But far be it from us that even for such, although we do not presume openly, we should cease to pray even in our hearts, since Paul also mourned those whom he knew dead without penitence. Yet let them see in how great danger they are, for whom the Church does not dare to pray openly, who confidently prays even for Jews, for heretics, for gentiles.", "But far be it from us that even for such, although we do not presume openly, we should cease to pray even in our hearts, since Paul also was mourning those whom he knew dead without penitence. Yet let them have seen in how great danger they are, for whom the Church does not dare to pray openly, who prays confidently even for Jews, for heretics, for gentiles."),
  ]),
  ch("admonitio", 23, "Admonitio in opusculum", "To Godfrey, on why pride was described", [
    one(
      "p57",
      "57",
      "Dicis forsitan, frater Godefride, me aliud quam tu quaesisti, quam ipse promisi, tandem exhibuisse, cum pro gradibus humilitatis, superbiae gradus videar descripsisse. Ad quod ego: non potui docere nisi quod didici. Non putavi congruum me describere ascensiones, qui plus descendere quam ascendere novi. Proponat tibi beatus Benedictus gradus humilitatis, quos ipse prius in corde suo disposuit; ego quid proponam non habeo, nisi ordinem meae descensionis. In quo tamen, si diligenter inspicitur, via forsitan ascensionis reperitur. Si enim tibi Romam tendenti homo inde veniens obviaret, quaesitus viam, quid melius quam illam, qua venit, ostenderet? Dum castella, villas et urbes, fluvios ac montes, per quos transierit, nominat, suum denuntians iter, tuum tibi praenuntiat, ita ut eadem loca recognoscas eundo, quae ille pertransiit veniendo. In hac similiter nostra descensione gradus ascensorios fortasse reperies, quos ascendendo melius tu in tuo corde quam in nostro codice leges.",
      "You will perhaps say, brother Godfrey, that I have at last exhibited something other than you asked, than I myself promised, since instead of the degrees of humility I seem to have described the degrees of pride. To which I: I could not teach except what I have learned. I did not think it fitting that I describe ascents, I who know more how to descend than to ascend. Let blessed Benedict propose to you the degrees of humility, which he himself first arranged in his heart; I have nothing to propose, except the order of my descent. In which nevertheless, if it is diligently looked into, the way of ascent is perhaps found. For if a man coming from there should meet you heading to Rome, asked the way, what better than that by which he came would he show? While he names the castles, villages and cities, rivers and mountains through which he shall have passed, announcing his journey, he foretells yours to you, so that you may recognize going the same places which he passed through coming. In this our descent similarly you will perhaps find the ascending degrees, which by ascending you will better read in your heart than in our book.",
      "You say perhaps, brother Godfrey, that I have at last exhibited something other than you asked, than I myself promised, since instead of the degrees of humility I seem to have described the degrees of pride. To which I: I could not teach except what I learned. I did not think it fitting that I describe ascents, I who know more to descend than to ascend. Let blessed Benedict set before you the degrees of humility, which he himself first arranged in his heart; I have nothing to set before, except the order of my descent. In which nevertheless, if it is diligently inspected, the way of ascent is perhaps found. For if to you heading to Rome a man coming from there should meet, asked the way, what better than that by which he came would he show? While he names the castles, villages and cities, rivers and mountains through which he shall have passed, announcing his journey, he foreannounces yours to you, so that going you may recognize the same places which he passed through coming. In this our descent similarly you will perhaps find the ascending degrees, which by ascending you will better read in your heart than in our codex.",
      [
        {
          kind: "theology",
          title: "the Rome road",
          body: "Bernard will not describe ascents he has not made. The same road is known by the one coming down. Mills’s ‘book’ is codice — the close line keeps codex, the written ladder versus the heart.",
        },
      ],
    ),
  ]),
];
